use std::collections::HashMap;
// join()
use itertools::Itertools;

use std::path::Path;
use crate::KEYWORDS;

type Parser = String;
type Parsers = HashMap<&'static str, Parser>;

fn make_grammar_js() -> String {
    format!(
r##"
/**
 * @file A Parser for the Zngur C++/Rust bindings language
 * @author cplir-c 31234188+cplir-c@users.noreply.github.com
 * @license Dual Apache 2.0 and MIT license
 *
 * Generated by `zngur/zngur-highlight --tree-sitter`
 *      (hence the poor formatting of e.g. the conditional_item).
 */

/// <reference types="tree-sitter-cli/dsl" />
// @ts-check

export default grammar({{
    name: "zngur",
    extras: $ => [ /\s/, $.comment ],
    reserved: {{
        keywords: $ => ['{keywords}'],
    }},
    word: $ => $.identifier,
    //externals: $ => [$.raw_string],
    rules: {{
        root: $ => repeat($.item),
        item: $ => choice(
            $.unstable_feature, // 1
            $.module, // 1
            $.type_item, // 1
            $.trait_item, // 1
            $.extern_cpp_item, // 1
            $.fn_item, // 1
            $.additional_include_item, // 1
            $.import_item, // 1
            $.module_import_item, // 1
            $.alias, // 1
            $.conditional_item // 1
        ),
        comment: $ => seq("//", /[^\n]*/),
        identifier:
            $ => new RustRegex('\\p{{XID_Start}}\\p{{XID_Continue}}*'),
        ident: $ => alias($.identifier, $.ident),
        number: $ => /0|[1-9][0-9]+/,
        token:
            $ => new RustRegex('[#]?\\p{{XID_Start}}\\p{{XID_Continue}}*'),

        // ... cancel this, we're using Rust-side text templates
        {conditional_item_},

        unstable_feature: $ => seq(
            '#unstable',
            // ident can be 'cfg_match', 'cfg_if', or 'template_types'
            '(', $.ident, ')'
        ),

        module_import_item: $ => seq(
            'import', $.plain_string, ';'
        ),

        import_item: $ => seq(
            'merge', $.plain_string, ';' // 1
        ),

        additional_include_item: $ => seq(
            choice(
                seq(
                    '#cpp_additional_includes',
                    $.rawable_string // 1
                ),
                '#convert_panic_to_exception'
            )
        ),

        fn_item: $ => seq(
            optional(choice('safe', 'unsafe')),
            $.function_signature, ';' // 1
        ),

        extern_cpp_item: $ => {{
            const safety = choice('safe', 'unsafe');
            const function_ = seq(
                safety, $.method_signature, ';' // 1, 1
            );
            // impl RustTrait for RustType {{ safety method; ... }}
            const impl_block = seq(
                'impl',
                optional(seq(
                    $.rust_trait, // 1
                    'for',
                )),
                $.rust_type, // 1
                '{{',
                repeat(seq(
                    safety, $.method_signature, ';' // 1, 1
                )),
                '}}',
            );
            return seq(
                'extern',
                '"C++"',
                '{{',
                repeat(choice(function_, impl_block)),
                '}}'
            );
        }},

        trait_item: $ => seq(
            'trait',
            $.rust_trait, // 1
            '{{', repeat(seq($.method, ';')), '}}' // TODO
        ),

        type_item: $ => seq(
            'type',
            optional(seq(
                '<',
                $.ident, repeat(seq(',', $.ident)), optional(','),
                '>'
            )),
            $.rust_type, // 1
            '{{', repeat($.inner_type_item), '}}' // 1
        ),

        module: $ => seq(
            'mod',
            $.path, // 1
            $.braced_items // 1
        ),
        braced_items: $ => seq(
            // 1, 1, 1
            '{{', repeat($.item), '}}'
        ),
        // lib.rs:3367
        path: $ => {{
            const start = optional(seq(
                choice(
                    '::',
                    seq(
                        'crate',
                        '::'
                    )
                )
            ));

            return prec.left(seq(
                start, // 1
                $.ident, // 1
                repeat(seq('::', $.ident)) // 1, 1
            ));
        }},
        // lib.rs:606
        // e.g. ? `use ::std::boxed::Box as Boxed;`
        alias: $ => seq(
            'use',
            $.path, // 1
            'as',
            $.ident, // 1
            ';'
        ),

        // lib.rs:2865
        function_signature: $ => {{
            const function_path = $.path; // 1

            return seq(
                optional('async'), 'fn',
                function_path, // 1
                optional(seq(
                    '<',
                    optional(seq(
                        $.rust_type, // 1
                        repeat(seq(',', $.rust_type)) // 1
                    )),
                    '>'
                )),
                $.fn_args // 1
            );
        }},

        // lib.rs:2842
        // Just like the function_signature,
        //      but with an identifier name instead of a path
        method_signature: $ => seq(
            optional('async'),
            'fn',
            $.ident,
            optional(seq(
                '<',
                optional(seq(
                    $.rust_type, // 1
                    repeat(seq(',', $.rust_type)) // 1
                )),
                '>'
            )),
            $.fn_args // 1
        ),

        // lib.rs:2811
        rust_trait: $ => {{
            const fn_trait = seq(
                $.ident, // 1
                $.fn_args // 1
            );

            return choice(
                fn_trait,
                $.rust_path_and_generics // 1
            );
        }},

        // lib.rs:2633
        rust_type_trait_bound: $ => seq(
            '+', $.path
        ),
        rust_type: $ => {{
            const adt = $.rust_path_and_generics; // 1

            const dyn_trait = seq(
                choice(
                    'dyn', 'impl'
                ),
                $.rust_trait,
                repeat($.rust_type_trait_bound)
            );

            const boxed = seq(
                'Box',
                $.rust_generics
            );

            const unit = seq('(', ')');
            const tuple = seq(
                '(',
                $.rust_type,
                repeat(seq(',', $.rust_type)),
                optional(','),
                ')'
            );
            const slice = seq('[', $.rust_type, ']');
            const reference = seq(
                '&', optional('mut'), $.rust_type
            );
            const raw_ptr = seq(
                '*', choice('mut', 'const'), $.rust_type
            );

            return prec.right(choice(
                $.rust_scalar,
                boxed,
                unit,
                tuple,
                slice,
                adt,
                reference,
                raw_ptr,
                dyn_trait
            ));
        }}, // rust_type
        rust_scalar: $ => choice(
            'bool', 'str', 'char', 'usize',
            'u8', 'u16', 'u32', 'u64', 'u128',
            'i8', 'i16', 'i32', 'i64', 'i128',
            'f32', 'f64'
        ),

        // lib.rs:52
        inner_type_property_item: $ => seq(
            $.ident, '=', $.number
        ),
        inner_type_trait_item: $ => choice(
            'Debug',
            'Copy',
            seq('?', 'Sized')
        ),
        inner_type_constructor_arg: $ => seq(
            choice(
                seq(
                    '(',
                    optional(seq(
                        $.rust_type,
                        repeat(seq(',', $.rust_type))
                    )),
                    ')'
                ),
                $.ident
            ),
            ':',
            $.rust_type
        ),
        inner_type_field: $ => seq(
            'field',
            choice($.ident, $.number),
            '(',
            repeat(seq(
                'offset', '=', choice($.number, 'auto'),
                ',', 'type', '=', $.rust_type
            )),
            ')'
        ),
        inner_type_inner_item: $ => {{
            const layout = choice(
                seq(
                    '#layout',
                    '(',
                    optional(seq(
                        $.inner_type_property_item,
                        repeat(seq(',', $.inner_type_property_item))
                    )),
                    ')'
                ), seq(
                    '#layout_conservative',
                    '(',
                    optional(seq(
                        $.inner_type_property_item,
                        repeat(seq(',', $.inner_type_property_item))
                    )),
                    ')'
                ),
                '#only_by_ref',
                '#heap_allocated'
            );

            const traits = seq(
                'wellknown_traits',
                '(',
                optional(seq(
                    $.inner_type_trait_item,
                    repeat(seq(',', $.inner_type_trait_item))
                )),
                ')'
            );
            
            const non_exhaustive = 'non_exhaustive';

            const constructor_args = optional(seq(
                '{{',
                optional(seq(
                    $.inner_type_constructor_arg,
                    repeat(seq(',', $.inner_type_constructor_arg))
                )),
                '}}'
            ));

            const constructor = seq(
                'constructor',
                constructor_args
            );

            const cpp_value = seq(
                '#cpp_value',
                $.plain_string,
                $.plain_string
            );

            const cpp_heap_allocated = seq(
                '#cpp_heap_allocated',
                $.plain_string
            );

            const cpp_ref = seq(
                '#cpp_ref',
                $.plain_string
            );

            const cpp_stack_owned = seq(
                '#cpp_stack_owned',
                $.plain_string,
                optional(seq(
                    '(',
                    optional(seq(
                        $.inner_type_property_item,
                        repeat(seq(',', $.inner_type_property_item))
                    )),
                    ')'
                ))
            );

            const inner_item = choice(
                layout,
                traits,
                non_exhaustive,
                constructor,
                $.inner_type_field,
                cpp_value,
                cpp_heap_allocated,
                cpp_ref,
                cpp_stack_owned,
                seq(
                    $.method, // TODO
                    optional(seq('use', $.path)),
                    optional(seq('deref', $.rust_type)),
                    optional(seq('as', $.ident))
                )
            );
            return prec.left(inner_item);
        }},

        inner_type_item: $ => {{
            const match_stmt = $.inner_type_conditional_item;

            const variant = seq(
                'variant',
                $.ident,
                '{{',
                repeat(seq(
                    choice(
                        'non_exhaustive',
                        $.inner_type_field
                    ),
                    ';'
                )),
                '}}'
            );

            return choice(
                match_stmt,
                variant,
                seq($.inner_type_inner_item, ';')
            );
        }}, // inner_type_item

        {conditional_inner_type_item},

        // lib.rs:2784
        fn_args: $ => seq(
            '(',
            optional(seq(
                $.rust_type,
                repeat(seq(
                    ',', $.rust_type
                )),
                optional(',')
            )),
            ')',
            optional(seq('->', $.rust_type))
        ),

        rust_path_and_generics: $ => {{
            const generics = $.rust_generics; // 1

            return seq(
                $.path,
                optional(generics)
            );
        }},

        rust_generics_named_generic: $ => {{
            const named_generic = seq(
                $.ident,
                '=',
                $.rust_type
            );
            return named_generic;
        }},
        rust_generics: $ => {{
            return seq(
                optional('::'),
                '<',
                optional(seq(
                    choice(
                        $.rust_generics_named_generic,
                        $.rust_type
                    ),
                    repeat(seq(
                        ',', choice(
                            $.rust_generics_named_generic,
                            $.rust_type
                        )
                    )),
                    optional(',')
                )),
                '>'
            );
        }},

        method: $ => seq(
            optional(choice(
                'safe', 'unsafe'
            )),
            $.method_signature
        ),
        
        plain_string: $ => /"(?:[\\]"|[^"])*"/,
        raw_string: $ => token(choice({raw_string_regexes})),
        rawable_string: $ => choice($.plain_string, $.raw_string)
    }}
}});
"##,
        keywords = KEYWORDS.iter()
            .filter(|&x| *x != "else" && *x != "match").join("', '"),
        conditional_item_ =
            conditional_item("$.item", "").into_iter()
            .map(|(name, body)| {
                format!("{name}: {body}")
            })
            .join(", "),
        conditional_inner_type_item =
            conditional_item(
                    "$.inner_type_inner_item",
                    "inner_type_"
                ).into_iter()
                .map(|(name, body)| {
                    format!("inner_type_{name}: {body}")
                })
                .join(", "),
        // tree-sitter-rust uses
        //      an external tokenizer for raw strings,
        //      but I'll try this
        raw_string_regexes = (
            (1..=20usize).rev().map(|n| {
                format!(
                    r##"seq(
                        new RustRegex('r#{{{n}}}"'),
                        repeat(token.immediate(/./)),
                        token.immediate(
                            new RustRegex('/"#{{{n}}}')
                        )
                    )"##,
                    n = n
                )
            }).join(", ")
        )
    )
}

pub(crate) fn emit_tree_sitter(folder: &str) -> Result<(), String> {
    let content = make_grammar_js();
    let folder = Path::new(folder);
    let tree_sitter_project_path = folder.join("tree-sitter-zngur");
    if let Some(err) = std::fs::create_dir(&tree_sitter_project_path).err() {
        if err.kind() != std::io::ErrorKind::AlreadyExists {
             return Err(format!("{}", err));
        }
        // else fallthrough
    } 
    let grammar_js_path = tree_sitter_project_path.join(
            "grammar.js"
        );
    std::fs::write(grammar_js_path, content)
            .map_err(|err| format!("{}", err))
}

